 1→import Plot from 'react-plotly.js';
 2→import { useTheme } from '../hooks/useTheme';
 3→
 4→interface ChartWidgetProps {
 5→  data: unknown[];
 6→  layout?: Record<string, unknown>;
 7→  frames?: unknown[];
 8→}
 9→
10→export function ChartWidget({ data, layout, frames }: ChartWidgetProps) {
11→  const { theme } = useTheme();
12→  const isDark = theme === 'dark';
13→
14→  // Normalize layout.title: Plotly v3 requires {text: "..."} object form
15→  const normalizedLayout = { ...layout };
16→  if (typeof normalizedLayout.title === 'string') {
17→    normalizedLayout.title = { text: normalizedLayout.title };
18→  }
19→
20→  // frames can live at the top level or inside layout (common variant);
21→  // extract from layout so Plotly receives them as a dedicated prop.
22→  const resolvedFrames = frames || (normalizedLayout.frames as unknown[]);
23→  delete normalizedLayout.frames;
24→
25→  // Theme-aware colors for Plotly
26→  const themeLayout = isDark
27→    ? {
28→        paper_bgcolor: 'rgba(0,0,0,0)',
29→        plot_bgcolor: 'rgba(0,0,0,0)',
30→        font: { color: '#e2e8f0' },
31→        xaxis: { gridcolor: '#374151', zerolinecolor: '#374151' },
32→        yaxis: { gridcolor: '#374151', zerolinecolor: '#374151' },
33→        legend: { font: { color: '#e2e8f0' } },
34→      }
35→    : {
36→        paper_bgcolor: 'rgba(0,0,0,0)',
37→        plot_bgcolor: 'rgba(0,0,0,0)',
38→      };
39→
40→  return (
41→    <Plot
42→      data={data as Plotly.Data[]}
43→      layout={{ autosize: true, height: 400, ...themeLayout, ...normalizedLayout } as Partial<Plotly.Layout>}
44→      frames={resolvedFrames as Plotly.Frame[] | undefined}
45→      useResizeHandler
46→      style={{ width: '100%' }}
47→      config={{ responsive: true, displayModeBar: true }}
48→    />
49→  );
50→}
